using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.Agents.AI;

var configuration = new ConfigurationBuilder()
    .AddEnvironmentVariables()
    .Build();

var apiKey = configuration["AI_API_KEY"]
    ?? throw new InvalidOperationException(
        "Set the AI_API_KEY environment variable to your OpenAI API key.");

var services = new ServiceCollection();

services.AddLogging(builder => builder
    .AddConsole()
    .SetMinimumLevel(LogLevel.Information));

services.AddChatClient(builder => builder
    .UseOpenAIChatClient("gpt-4o-mini-2024-07-18", apiKey));

var provider = services.BuildServiceProvider();
var chatClient = provider.GetRequiredService<IChatClient>();
var logger = provider.GetRequiredService<ILogger<Program>>();

// Define the tools available to the agent
var tools = new ResearchTools();
var chatOptions = new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
    Tools = [
        AIFunctionFactory.Create(tools.SearchWeb),
        AIFunctionFactory.Create(tools.TakeNote),
        AIFunctionFactory.Create(tools.GetNotes),
    ],
};

// Create the agent using Microsoft Agent Framework
var agent = new ChatClientAgent(chatClient, chatOptions)
{
    Name = "ResearchAgent",
    Description = "An agent that researches topics by searching the web and taking notes.",
    Instructions = """
        You are a research assistant. When given a topic:
        1. Search the web for relevant information (perform 2-3 searches with different queries).
        2. Take notes on key findings from each search.
        3. Review your notes and provide a comprehensive summary of your research.
        Always cite your sources. Be thorough but concise.
        """,
};

// Get topic from command line or prompt the user
var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍 Researching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
};

var invokeOptions = new AgentInvokeOptions
{
    MaximumIterations = 10,
};

// Run the agent loop
await foreach (var message in agent.InvokeStreamingAsync(history, invokeOptions))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n📝 Notes collected during research:");
foreach (var note in tools.Notes)
{
    Console.WriteLine($"  • {note}");
}

static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var topic = Console.ReadLine();
    return string.IsNullOrWhiteSpace(topic)
        ? throw new InvalidOperationException("A research topic is required.")
        : topic;
}

/// <summary>
/// Tools available to the research agent for web search and note-taking.
/// </summary>
sealed class ResearchTools
{
    private readonly List<string> _notes = [];
    private readonly HttpClient _httpClient = new();

    public IReadOnlyList<string> Notes => _notes;

    [Description("Search the web for information on a query. Returns search results as text.")]
    public async Task<string> SearchWeb(
        [Description("The search query to look up")] string query)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        try
        {
            // Use a web search API (DuckDuckGo instant answer as a free fallback)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var response = await _httpClient.GetStringAsync(url);

            // Parse the JSON response for useful content
            using var doc = System.Text.Json.JsonDocument.Parse(response);
            var root = doc.RootElement;

            var results = new List<string>();

            var abstractText = root.GetProperty("AbstractText").GetString();
